package org.apache.hive.beeline;

import java.sql.SQLException;
import java.sql.Statement;

import sun.misc.Signal;
import sun.misc.SignalHandler;

import org.apache.hadoop.util.ExitUtil;

public class SunSignalHandler implements BeeLineSignalHandler, SignalHandler {
  private Statement stmt = null;
  private final BeeLine beeLine;

  SunSignalHandler (BeeLine beeLine) {
    this.beeLine = beeLine;
    // Interpret Ctrl+C as a request to cancel the currently
    // executing query.
    Signal.handle (new Signal ("INT"), this);
  }

  @Override
  public void setStatement(Statement stmt) {
    this.stmt = stmt;
  }

  @Override
  public void handle (Signal signal) {
    try {
      // exit the JVM if Ctrl+C is received
      // and no current statement is executing
      if(stmt == null || stmt.isClosed()) {
        ExitUtil.terminate(127);
      } else {
        beeLine.info(beeLine.loc("interrupt-ctrl-c"));
        stmt.cancel();
      }
    } catch (SQLException ex) {
      // ignore
    }
  }
}","lineStart":1,"lineEnd":64,"totalLines":64,"truncated":false}},"title":"repos/software42/hive/beeline/src/java/org/apache/hive/beeline/SunSignalHandler.java","time":{"start":1783267065087,"end":1783267065091}},"id":"prt_f32fffab6001EVVqSRz4a3Lv0H","sessionID":"ses_0cd0260ecffeIIM7y4g9DQ6hbT","messageID":"msg_f32ffe3bc0010SSXg72puw2nJT"}}

